def process(areaStateIntersections) -> pd.DataFrame:
    import pandas as pd
    if areaStateIntersections.shape[0] == 0:
        return pd.DataFrame([{'abbr': None}])
    return pd.DataFrame([{'abbr': str(areaStateIntersections.iloc[0]['abbr'])}])

def load() -> pd.DataFrame:
    import geopandas as gpd
    import pandas as pd

    path = 'data/wildfire/input/usa.gpkg'
    layer = 'usa_adm2'

    gdf = gpd.read_file(path, layer=layer)

    # Identify a state-level grouping key
    if 'adm1_code' in gdf.columns:
        by = 'adm1_code'
    elif 'adm1_name' in gdf.columns:
        by = 'adm1_name'
    elif 'name_1' in gdf.columns:
        by = 'name_1'
    elif 'NAME_1' in gdf.columns:
        by = 'NAME_1'
    elif 'state' in gdf.columns:
        by = 'state'
    else:
        by = None

    if by is None:
        raise ValueError(f"Could not find a state-level key in columns: {list(gdf.columns)[:50]}")

    # GeoPandas dissolve returns a GeoDataFrame; keep it that way
    statesGdf = gdf[[by, 'geometry']].dissolve(by=by).reset_index()

    # Ensure CRS is set (assume WGS84 if missing)
    if statesGdf.crs is None:
        statesGdf = statesGdf.set_crs('EPSG:4326')

    # Serialize geometry to WKT and return a plain pandas DataFrame
    out = pd.DataFrame({
        'stateKey': statesGdf[by].astype(str),
        'geometryWkt': statesGdf.geometry.to_wkt()
    })
    return out
